-- ============================================================================
-- Bulk image riddles seed (web-extracted riddles, added 2026-09-15)
-- ============================================================================
-- Remapped 2026-09-15 to the 10 owner-approved launch categories; 150 of the
-- original 200 riddles survive. The 50 Famous Artwork rows were dropped (the
-- category no longer exists). Remaps: old Hidden Objects rows -> Animal
-- Camouflage (their titles are camouflage animals); Pattern Recognition,
-- Perspective Puzzles and Color Observation rows -> Optical Illusions;
-- vintage find-the-differences rows -> Spot the Difference, the remaining
-- vintage rows -> Hidden Objects.
-- CATEGORIES ARE NOT SEEDED HERE - run sample-image-riddles.sql (or
-- reset-image-riddle-content.js) first so the 10 canonical rows exist.
-- Every image is a REAL Wikimedia Commons file: URL, mime, size and license
-- verified via the Commons API (prop=imageinfo) on 2026-09-15; only
-- PD/CC0/CC BY/CC BY-SA. Each row carries a Source link action (attribution
-- surface, do not remove).
-- Idempotent: ON CONFLICT DO UPDATE.
-- AFTER RESEEDING flush the categories cache:
--   docker exec ai-quiz-redis redis-cli DEL image-riddles:categories
-- ============================================================================

ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  "imageUrl" = EXCLUDED."imageUrl",
  answer = EXCLUDED.answer,
  "alternativeAnswers" = EXCLUDED."alternativeAnswers",
  hint = EXCLUDED.hint,
  difficulty = EXCLUDED.difficulty,
  "timerSeconds" = EXCLUDED."timerSeconds",
  "altText" = EXCLUDED."altText",
  "categoryId" = EXCLUDED."categoryId",
  status = EXCLUDED.status,
  "actionOptions" = EXCLUDED."actionOptions";

-- Purge guard: trash any bulk riddle whose row was intentionally removed above (no-op here)
